/// Exact SVG icon paths ported from deepseek-ai/chat-demo `icons.tsx`
/// plus the DeepSeek whale emblem.
class DsIcons {
  static Widget svg(
    String rawSvg, {
    double size = 16,
    Color? color,
  }) {
    return SvgPicture.string(
      rawSvg,
      width: size,
      height: size,
      colorFilter:
          color != null ? ColorFilter.mode(color, BlendMode.srcIn) : null,
    );
  }

